export const VERSE_MEANINGS: Record<string, string> = {
  "94:5-6": "与艰难相伴的，确是容易， 与艰难相伴的，确是容易，",
  "2:286-286": "安拉只依各人的能力而加以责成。各人要享受自己所行善功的奖赏，要遭遇自己所作罪恶的惩罚。“我们的主啊！求你不要惩罚我们，如果我们遗忘或错误。求你不要使我们荷负重担，犹如你使古人荷负它一样。我们的主啊！求你不要使我们担负我们所不能胜任的。求你恕饶我们，求你赦宥我们，求你怜悯我们。你是我们的保佑者。求你援助我们，以对抗不信道的民众。”",
  "20:114-114": "安拉是超绝万物，宰制众生，体用真实的。对你启示《古兰经》还没有完全的时候，你不要急忙诵读。你说：“我的主啊！求你增加我的知识。”",
  "13:28-28": "他们信道，他们的心境因铭记安拉而安静，真的，一切心境因铭记安拉而安静。",
  "2:152-152": "故你们当铭记我，我也就铭记你们；你们当感谢我；不要孤负我。",
  "2:153-153": "信道的人们啊！你们当借坚忍和拜功而求佑助。安拉确是与坚忍者同在的。",
  "14:7-7": "当时，你们的主曾宣布说：“如果你们感谢，我誓必对你们恩上加恩；如果你们忘恩负义，那么，我的刑罚确是严厉的。”",
  "65:3-3": "而且从他料想不到的地方供给他。谁托靠安拉，他将使谁满足。安拉确是能达到自己的目的的，安拉确已使万物各有定数。",
  "39:53-53": "你说：“我的过分的自害的众仆啊！你们对安拉的恩惠不要绝望，安拉必定赦宥一切罪过，他确是至赦的，确是至慈的。",
  "3:139-139": "你们不要灰心，不要忧愁，你们必占优势，如果你们是信道的人。",
  "9:40-40": "如果你们不相助他，那么，安拉确已相助他了。当时，不信道的人们把他驱逐出境，只有一个人与他同行，当时，他俩在山洞里，他对他的同伴说：“不要忧愁，安拉确是和我们在一起的。”安拉就把宁静降给他，而且以你们看不见的军队扶助他，并且使不信道者的言词变成最卑贱的；而安拉的言词确是最高尚的。安拉是万能的，是至睿的。",
  "12:87-87": "他说：“我的孩子们！你们去打听优素福和他弟弟的消息吧。你们不要绝望于安拉的慈恩，只有不信道的人们才绝望于安拉的慈恩。”",
  "53:39-40": "各人只得享受自己的劳绩； 他的劳绩，将被看见，",
  "13:11-11": "每个人的前面和后面，都有许多接踵而来的天使，他们奉安拉的命令来监护他。安拉必定不变更任何民众的情况，直到他们变更自己的情况。当安拉欲降灾害于任何民众的时候，那灾害是不可抗拒的。除安拉外，他们绝无保护者。",
  "29:69-69": "为我而奋斗的人，我必定指引他们我的道路，安拉确是与善人同在一起的。",
  "3:159-159": "只因为从安拉发出的慈恩，你温和地对待他们；假若你是粗暴的，是残酷的，那么，他们必定离你而分散；故你当恕饶他们，当为他们向主求饶，当与他们商议公事；你既决计行事，就当托靠安拉。安拉的确喜爱托靠他的人。",
  "16:97-97": "凡行善的男女信士，我誓必要使他们过一种美满的生活，我誓必要以他们所行的最大善功报酬他们。",
  "103:1-3": "以时光盟誓， 人确是在亏折之中， 惟信道而且行善，并以真理相劝，以坚忍相勉的人则不然。",
  "54:17-17": "我确已使《古兰经》易于记读，有接受劝告的人吗？",
  "73:4-4": "或多一点。你应当讽诵《古兰经》，",
  "96:1-5": "你应当奉你的创造主的名义而宣读， 他曾用血块创造人。 你应当宣读，你的主是最尊严的， 他曾教人用笔写字， 他曾教人知道自己所不知道的东西。",
  "58:11-11": "信道的人们啊！有人在会场中对你们说：“请你们退让一点吧！”你们就应当退让些，安拉将使你们宽裕。有人对你们说：“你们起来吧！”你们就应当起来，安拉将你们中的信道的人和有学问的人们提升若干级。安拉是彻知你们的行为的。",
  "39:9-9": "（景况更好的，是你呢？）还是在夜间专心事主，叩头立正，谨防后世，希望主恩的人呢？”你说：“有知识的与无知识的相等吗？惟有理智的人能觉悟。”",
  "35:28-28": "人类，野兽和牲畜中，也同样地有不同的种类。安拉的仆人中，只有学者敬畏他。安拉确是万能的，确是至赦的。",
  "2:45-45": "你们当借坚忍和礼拜而求祐助。礼拜确是一件难事，但对恭敬的人却不难。",
  "2:155-156": "我必以些微的恐怖和饥馑，以及资产、生命、收获等的损失，试验你们，你当向坚忍的人报喜。 他们遭难的时候，说：“我们确是安拉所有的，我们必定只归依他。”",
  "2:186-186": "如果我的仆人询问我的情状，你就告诉他们：我确是临近的，确是答应祈祷者的祈祷的。当他祈祷我的时候，教他们答应我，信仰我，以便他们遵循正道。",
  "40:60-60": "你们的主说：“你们要祈祷我，我就应答你们；不肯崇拜我的骄傲自大者们，他们将卑贱地入火狱。”",
  "50:16-16": "我确已创造人，我知道他心中的妄想；我比他的命脉还近于他。",
  "57:4-4": "他是在六日内创造天地，然后升上宝座的。他知道潜入地中的，和从地中生出的，与从天空降下的，和升上天空的。无论你们在哪里，他是与你们同在的；他是鉴察你们的行为的。",
  "2:216-216": "战争已成为你们的定制，而战争是你们所厌恶的。也许你们厌恶某件事，而那件事对于你们是有益的；或许你们喜爱某件事，而那件事对于你们是有害的。安拉知道，你们确不知道。",
  "3:134-134": "敬畏的人，在康乐时施舍，在艰难时也施舍，且能抑怒、又能恕人。安拉是喜爱行善者的。",
  "41:34-34": "善恶不是一样的。你应当以最美的品行去对付恶劣的品行，那么，与你相仇者，忽然间变的亲如密友。",
  "49:12-12": "信道的人们啊！你们应当远离许多猜疑；有些猜疑，确是罪过。你们不要互相侦探，不要互相背毁，难道你们中有人喜欢吃他的已死的弟兄的肉吗？你们是厌恶那种行为的。你们应当敬畏安拉，安拉确是至赦的，确是至慈的。",
  "49:13-13": "众人啊！我确已从一男一女创造你们，我使你们成为许多民族和部落，以便你们互相认识。在安拉看来，你们中最尊贵者，是你们中最敬畏者。安拉确是全知的，确是彻知的。",
  "17:24-24": "你应当必恭必敬地服侍他俩，你应当说：“我的主啊！求你怜悯他俩，就像我幼年时他俩养育我那样。”",
  "31:17-17": "我的小儿子啊！你应当谨守拜功，应当劝善戒恶，应当忍受患难，这确是应该决心做的事情。",
  "25:63-63": "至仁主的仆人是在大地上谦逊而行的；当愚人以恶言伤害他们的时候，他们说：“祝你们平安。”",
  "7:31-31": "阿丹的子孙啊！每逢礼拜，你们必须穿着服饰。你们应当吃，你们应当喝，但不要浪费，安拉确是不喜欢浪费者的。",
  "16:69-69": "然后，你从每种果实上吃一点，并驯服地遵循你的主的道路。”将有一种颜色不同，而可以治病的饮料，从它的腹中吐出来；对于能思维的民众，此中确有一种迹象。",
  "26:80-80": "我害病时，是他使我痊愈的。",
  "21:30-30": "不信道者难道不知道吗？天地原是闭塞的，而我开天辟地，我用水创造一切生物。难道他们不信吗？",
  "51:49-49": "我将每种物造成配偶，以便你们觉悟。",
  "51:20-21": "对于笃信的人们，大地上有许多迹象； 在你们自身中也有许多迹象，难道你们看不见吗？",
  "41:53-53": "我将在四方和在他们自身中，把我的许多迹象昭示他们，直到他们明白《古兰经》确是真理。难道你的主能见证万物还不够吗？",
  "3:190-190": "天地的创造，昼夜的轮流，在有理智的人看来，此中确有许多迹象。",
  "36:40-40": "太阳不得追及月亮，黑夜也不得超越白昼，各在一个轨道上浮游着。",
  "55:1-4": "至仁主， 曾教授《古兰经》， 他创造了人， 并教人修辞。",
  "55:13-13": "你们究竟否认你们的主的哪一件恩典呢？",
  "93:3-5": "你的主没有弃绝你，也没有怨恨你； 后世于你，确比今世更好； 你的主将来必赏赐你，以至你喜悦。",
  "94:7-8": "当你的事务完毕时， 你应当勤劳，你应当向你的主恳求。",
  "2:201-201": "有人说：“我们的主啊！求你在今世赏赐我们美好的（生活），在后世也赏赐我们美好的（生活），求你保护我们，免受火狱的刑罚。”",
  "3:8-8": "我们的主啊！在你引导我们之后，求你不要使我们的心背离正道，求你把从你那里发出的恩惠赏赐我们；你确是博施的。",
  "20:25-28": "他说：“我的主啊！求你使我的心情舒畅， 求你使我的事业顺利， 求你解除我的口吃， 以便他们了解我的话。",
  "18:23-24": "你不要为某事而说：“明天我一定做那件事。” 除非同时说：“如果安拉意欲。”你如果忘了，就应当记忆起你的主，并且说：“我的主或许指示我比这更切近的正道。”",
  "28:24-24": "他就替她俩饮羊，然后退到树荫下，他说：“我的主啊！我确需求你所降给我的任何福利。”",
  "21:87-87": "（你应当叙述）左农，当时他曾愤愤不平地离去，他猜想我绝不约束他，他在重重黑暗中呼吁（说）：“除你之外，绝无应受崇拜者，我赞颂你超绝万物，我确是不义的。”",
  "21:83-83": "（你应当叙述）艾优卜，当时他曾呼吁他的主，说：“痼疾确已伤害我，你是最仁慈的。”",
  "12:86-86": "他说：“我只向安拉诉说我的忧伤，我从安拉那里知道你们所不知道的。”",
  "12:18-18": "他们用假血染了优素福的衬衣，拿来给他们的父亲看。他说：“不然，你们的私欲怂恿你们干了这件事；我只有很好地忍耐，对你们所叙述的事，我只能求助于安拉！”",
  "70:5-5": "你安然地忍受吧。",
  "16:128-128": "安拉确是同敬畏者和行善者在一起的。",
  "11:115-115": "你当坚忍，因为安拉必不使行善者徒劳无酬。",
  "18:46-46": "财产和后嗣是今世生活的装饰：常存的善功，在你的主看来，是报酬更好的，是希望更大的。",
  "57:23-23": "以免你们为自己所丧失的而悲伤，为他所赏赐你们的而狂喜。安拉是不喜爱一切傲慢者、矜夸者的。",
  "64:16-16": "你们当量力地敬畏安拉，你们当听从他的教训和命令，你们当施舍，那是有益于你们自己的。能戒除自身的贪吝者，确是成功的。",
  "2:185-185": "赖买丹月中，开始降示《古兰经》，指导世人，昭示明证，以便遵循正道，分辨真伪，故在此月中，你们应当斋戒；害病或旅行的人，当依所缺的日数补斋。安拉要你们便利，不要你们困难，以便你们补足所缺的日数，以便你们赞颂安拉引导你们的恩德，以便你们感谢他。",
  "4:28-28": "安拉欲减轻你们的负担；人是被造成懦弱的。",
  "47:7-7": "信道的人们啊！如果你们相助安拉，他就相助你们，并使你们脚步稳固。",
  "8:46-46": "你们当服从安拉及其使者，你们不要纷争；否则，你们必定胆怯，你们的实力必定消失；你们应当坚忍，安拉确是同坚忍者同在的。",
  "61:2-3": "信道的人们啊！你们为什么说你们所不做的事呢？ 你们说你们所不做的，这在安拉看来，是很可恨的。",
  "9:105-105": "你说：“你们工作吧！安拉及其使者和信士们都要看见你们的工作；你们将被送到全知幽明者那里去，而他要将你们的工作告诉你们。”",
  "67:2-2": "他曾创造了死生，以便他考验你们谁的作为是最优美的。他是万能的，是至赦的。",
  "18:30-30": "信道而且行善者，我必不使他们的善行徒劳无酬，",
  "2:195-195": "你们当为主道而施舍，你们不要自投于灭亡。你们应当行善；安拉的确喜爱行善的人。",
  "28:77-77": "你应当借安拉赏赐你的财富而营谋后世的住宅，你不要忘却你在今世的定分。你应当善待人，像安拉善待你一样。你不要在地方上摆弄是非，安拉确是不爱摆弄是非者。”",
  "17:36-36": "你不要随从你所不知道的言行，耳目和心灵都是要被审问的。",
  "5:8-8": "信道的人们啊！你们当尽忠报主，当秉公作证，你们绝不要因为怨恨一伙人而不公道，你们当公道，公道是最近于敬畏的。你们当敬畏安拉。安拉确是彻知你们的行为的。",
  "16:90-90": "安拉的确命人公平、行善、施济亲戚，并禁人淫乱、作恶事、霸道；他劝戒你们，以便你们记取教诲。",
  "24:22-22": "你们中有恩惠和财富者不可发誓（说）：永不周济亲戚、贫民及为主道而迁居者。他们应当恕饶，应当原谅。难道你们不愿安拉赦宥你们吗？安拉是至赦的，是至慈的。",
  "42:43-43": "凡能忍受而加以赦宥者，他们的那种行为，确是应该决心做的事情。",
  "2:263-263": "与其在施舍之后，损害受施的人，不如以婉言谢绝他，并赦宥他的烦扰。安拉是自足的，是至容的。",
  "17:53-53": "你告诉我的仆人们说：叫他们说这句最优美的话——恶魔必定要离间他们，恶魔确是人类的明敌——",
  "2:83-83": "当时，我与以色列的后裔缔约，说：“你们应当只崇拜安拉，并当孝敬父母，和睦亲戚，怜恤孤儿，赈济贫民，对人说善言，谨守拜功，完纳天课。”然后，你们除少数人外，都违背约言，你们是常常爽约的。",
  "6:162-162": "你说：“我的礼拜，我的牺牲，我的生活，我的死亡，的确都是为了安拉——众世界的主。",
  "51:56-56": "我创造精灵和人类，只为要他们崇拜我。",
  "3:200-200": "信道的人们啊！你们当坚忍、当奋斗、当戒备、当敬畏安拉，以便你们成功。！",
  "29:45-45": "你应当宣读启示给你的经典，你当谨守拜功，拜功的确能防止丑事和罪恶，记念安拉确是一件更大的事，安拉知道你们的做为。",
  "33:41-42": "信士们啊！你们应当常常记念安拉， 你们应当朝夕赞颂他超绝万物。",
  "50:39-39": "故你应当忍受他们所说的谰言。在日出日落之前，你应当赞颂你的主；",
  "2:269-269": "他以智慧赋予他所意欲的人；谁禀赋智慧，谁确已获得许多福利。惟有理智的人，才会觉悟。",
  "31:12-12": "我确已把智慧赏赐鲁格曼，（我说）：“你当感谢安拉。感谢的人，只为自己而感谢，孤负的人，须知安拉确是无求的，确是可颂的。”",
  "25:74-74": "他们说：“我们的主啊！求你以我们的妻子儿女为我们的安慰，求你以我们为敬畏者的典范。”",
  "46:15-15": "我曾命人孝敬父母；他的母亲，辛苦地怀着他，辛苦地生他，在他受胎和断乳的时期，共计是三十个月。当他达到壮年，再达到四十岁的时候，他说：“我的主啊！求你启示我，使我感谢你所施于我和我的父母的恩惠，并行你所喜悦的善事。求你为我改善我的后裔。我确已向你悔罪，我确是一个顺服者。”",
  "14:40-40": "我的主啊！求你使我和一部分后裔谨守拜功。我们的主啊！求你接受我的祈祷。",
  "7:56-56": "在改善地方之后，你们不要在地方上作恶，你们要怀着恐惧和希望的心情祈祷他。安拉的慈恩确是临近行善者的。",
  "30:21-21": "他的一种迹象是：他从你们的同类中为你们创造配偶，以便你们依恋她们，并且使你们互相爱悦，互相怜恤。对于能思维的民众，此中确有许多迹象。",
  "30:22-22": "他的一种迹象是：天地的创造，以及你们的语言和肤色的差异，对于有学问的人，此中确有许多迹象。",
  "88:17-20": "难道他们不观察吗？骆驼是怎样造成的， 天是怎样被升高的， 山峦是怎样被竖立起的， 大地是怎样被展开的。",
  "80:24-24": "教人观察自己的食物吧！",
  "39:10-10": "你说：“我的信道的众仆啊！你们当敬畏你们的主。在今世行善者，得享美报。安拉的地面是宽广的；惟有坚忍的人，得享受完全的、无量的报酬。”",
  "89:27-30": "安定的灵魂啊！ 你应当喜悦地，被喜悦地归于你的主。 你应当入在我的众仆里； 你应当入在我的乐园里。",
  "91:9-10": "凡培养自己的性灵者，必定成功； 凡戕害自己的性灵者，必定失败。",
  "79:40-41": "至于怕站在主的御前受审问，并戒除私欲的人， 乐园必为他的归宿。",
  "12:53-53": "（他说）：“我不自称清白；人性的确是怂恿人作恶的，除非我的主所怜悯的人。我的主确是至赦的，确是至慈的。”",
  "75:14-15": "不然，各人对自己就是明证， 即使他多方托辞。",
  "99:7-8": "行一个小蚂蚁重的善事者，将见其报酬； 作一个小蚂蚁重的恶事者，也将见其恶报。",
  "2:110-110": "你们应当谨守拜功，完纳天课。凡你们为自己而行的善，你们将在安拉那里发现其报酬。安拉却是明察你们的行为的。",
  "3:92-92": "你们绝不能获得全善，直到你们分舍自己所爱的事物。你们所施舍的，无论是什么，确是安拉所知道的。",
  "2:261-261": "为主道而施舍财产的人，譬如（一个农夫，播下）一粒谷种，发出七穗，每穗结一百颗谷粒。安拉加倍地报酬他所意欲的人，安拉是宽大的，是全知的。",
  "14:24-25": "难道你不知道安拉有过这样一个比喻吗？一句良言，好比一棵优良的树，其根柢是深固的，其枝条高耸入云， 凭主的许可，按时结果。安拉为众人打了许多比方，以便他们记取教诲。",
  "112:1-4": "你说：“他是安拉，是独一的主； 安拉是万物所仰赖的； 他未生育， 也未被生育。 没有任何物可以做他的匹敌。”",
  "59:18-18": "信道的人们啊！你们应当敬畏安拉，各人应当想一想自己为明日而预备了什么，你们应当敬畏安拉，安拉确是彻知你们的行为的。",
  "65:7-7": "教富裕的人用他的富裕的财产去供给， 教窘迫的人用安拉所赏赐他的去供给。安拉只依他所赋予人的能力而加以责成。在窘迫之后，安拉将给宽裕。",
  "3:173-173": "有人曾对他们说：“那些人确已为进攻你们而集合队伍了，故你们应当畏惧他们。”这句话却增加了他们的信念，他们说：“安拉是使我们满足的，他是优美的监护者！”",
  "17:80-80": "你说：“我的主啊！求你使我顺利而入，求你使我顺利而出，求你赏赐我从你那里发出的权柄，以作我的辅弼。”",
  "18:10-10": "当时，有几个青年避居山洞中，他们说：我们的主啊！求你把你那里的恩惠赏赐我们，求你使我们的事业完全端正。",
  "20:46-46": "主说：“你俩不要怕，我的确同你俩在一起，我听着，而且看着。",
}
